out = Path(__file__).resolve().parent.parent / 'lang'
out.mkdir(exist_ok=True)
seen = set()
for en, *_ in ROWS:
    assert en not in seen, f'twice: {en}'
    seen.add(en)
for i, code in enumerate(CODES):
    words = {row[0]: row[1 + i] for row in ROWS}
    pats = [[p[0], p[1 + i]] for p in PATTERNS]
    js = ('// UsForge in ' + code + ' — made by scripts/langs.py (edit the table there, not this file)\n'
          'window.USF_DICT = ' + json.dumps(words, ensure_ascii=False, indent=0) + ';\n'
          'window.USF_PATTERNS = ' + json.dumps(pats, ensure_ascii=False) + ';\n')
    (out / f'{code}.js').write_text(js, encoding='utf-8')
print(f'{len(ROWS)} sentences and {len(PATTERNS)} patterns in {len(CODES)} languages')
